joi_block.script:
phase := 0
if (phase == 0) {
wait until((#SR_Humid).humiditySensor_humidity > 70)
phase = 1
}
(#Lab_Dehum).dehumidifier_setDehumidifierMode("dehumidifying")

h = (#SR_Humid).humiditySensor_humidity
if (h < 50) {
(#Lab_Dehum).switch_off()
}

fired := false
if (fired == true) {
wait until(not (all(#MotionSensor).motionSensor_motion == true))
fired = false
}
wait until(all(#MotionSensor).motionSensor_motion == true)
(#Living_Light).light_movetobrightness((#Living_Light).light_currentBrightness + 10, 0)
if ((#Living_Light).light_currentBrightness >= 100) {
break
}
fired = true

triggered := false
if (triggered == true) {
    wait until((#LivingRoom_MB).multiButton_button4 == "pushed")
    triggered = false
}
wait until((#LivingRoom_MB).multiButton_button4 == "pushed")
tmp = (#LivingRoom_Light).levelControl_currentLevel - 15
if (tmp < 10) {
    tmp = 10
}
(#LivingRoom_Light).levelControl_moveToLevel(tmp, 0.0)
triggered = true

all(#DoorLock).doorlock_lock()
wait until((#Clock).clock_hour < 6)
if ((#Living_Light).levelControl_currentLevel > 30) {
(#Living_Light).levelControl_moveToLevel(10, 0)
}

hold_ticks := 0
if ((#Kitchen_ContactSensor).contactSensor_contact == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 6001) {
(#Kitchen_Fan).switch_on()
        break
}
}
else {
hold_ticks = 0
}

hold_ticks := 0
if ((#Office_Presence).presenceSensor_presence == false) {
    hold_ticks = hold_ticks + 1
    if (hold_ticks >= 6001) {
        (#Office_AC).switch_off()
        break
    }
} else {
    hold_ticks = 0
}

hold_ticks := 0
if ((#Study_Presence).presenceSensor_presence == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 9001) {
(#Study_Light).light_moveToBrightness(20.0, 0.0)
        delay(10 MIN)
(#Study_Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

hold_ticks := 0
if ((#Bedroom_Temp).temperatureSensor_temperature > 28) {
hold_ticks = hold_ticks + 1
if (hold_ticks >= 3001) {
(#Bedroom_Fan).switch_on()
break
}
}
else {
hold_ticks = 0
}
delay(20 MIN)
(#Bedroom_Fan).switch_off()

hold_ticks := 0
if ((#Hallway_Motion).motionSensor_motion == false) {
    hold_ticks = hold_ticks + 1
    if (hold_ticks >= 1801) {
        (#Hallway_Light).light_moveToBrightness(50, 0)
        delay(2 MIN)
        (#Hallway_Light).switch_off()
    }
} else {
    hold_ticks = 0
}

hold := 0
if ((#Office_Plug).plug_power < 5) {
    hold = hold + 1
    if (hold >= 6001) {
        (#Office_Speaker).speaker_speak("Device is idle")
        delay(2 MIN)
        (#Office_Speaker).speaker_speak("Device is idle")
        delay(2 MIN)
        (#Office_Speaker).speaker_speak("Device is idle")
        break
    }
} else {
    hold = 0
}

hold_ticks := 0
if ((#Lobby_Presence).presenceSensor_presence == false) {
hold_ticks = hold_ticks + 1
if (hold_ticks >= 601) {
(#Lobby_Speaker).speaker_speak("Is anyone there")
delay(15 SEC)
(#Lobby_Speaker).speaker_speak("Is anyone there")
delay(15 SEC)
(#Lobby_Speaker).speaker_speak("Is anyone there")
delay(15 SEC)
(#Lobby_Speaker).speaker_speak("Is anyone there")
}
else {
hold_ticks = 0
}
}

hold := 0
if ((#Safe_ContactSensor).contactSensor_contact == true) {
    hold = hold + 1
    if (hold >= 301) {
        (#Safe_Camera).camera_captureImage()
        delay(30 SEC)
        (#Safe_Camera).camera_captureImage()
        delay(30 SEC)
        (#Safe_Camera).camera_captureImage()
        delay(30 SEC)
        (#Safe_Camera).camera_captureImage()
        delay(30 SEC)
        (#Safe_Camera).camera_captureImage()
        break
    }
} else {
    hold = 0
}
